const base = require('@salesforce/pwa-kit-dev/configs/babel/babel-config');
const baseConfig = base.default || base;

// Path aliases — kept in sync with tsconfig.json paths and .storybook/main.js webpackFinal.
// (jest.config.js's moduleNameMapper is separate — for @salesforce/pwa-kit-dev internals only)
//   ~   → project root
//   app → overrides/app
module.exports = {
  ...baseConfig,
  plugins: [
    ...baseConfig.plugins,
    [
      require.resolve('babel-plugin-module-resolver'),
      {
        root: ['.'],
        alias: {
          '~': '.',
          app: './overrides/app',
        },
      },
    ],
  ],
};

=== tsconfig.json paths ===
{
  "compilerOptions": {
    // Type-checking only — Babel handles transpilation.
    "noEmit": true,

    // Path aliases — keep in sync with babel.config.js, vitest.config.ts, .storybook/main.js
    // (jest.config.js has its own separate alias entries for @salesforce/pwa-kit-dev's
    // internal tooling — see .docs/architecture.md — not part of this sync group)
    "paths": {
      "~/*": ["./*"],
      "app/*": ["./overrides/app/*"]
    },
    "isolatedModules": true,

    // Language
    "target": "ES2019",
    "lib": ["ES2019", "DOM"],
    "jsx": "react-jsx",

    // Modules
    "module": "ESNext",
    "moduleResolution": "bundler",
    "esModuleInterop": true,

    // Strictness
    "strict": true,

    // Skip type-checking of vendored .d.ts files in node_modules.
    "skipLibCheck": true
  },
  "include": ["overrides/**/*", "vitest.config.ts", "vitest.setup.ts"]
}

=== vitest.config.ts ===
import { defineConfig } from 'vitest/config';
import path from 'path';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./vitest.setup.ts'],
    include: ['overrides/**/*.test.ts', 'overrides/**/*.test.tsx'],
    passWithNoTests: true,
    coverage: {
      provider: 'v8',
      // Force-includes every file under overrides/ at 0% if no test ever
      // imports it — without this, coverage only reports on the files the
      // 16 (as of 2026-08-26) existing test files happen to import, which
      // reads as a misleadingly high percentage of a much smaller universe
      // than "overrides/" as a whole (added at the developer's explicit
      // request for whole-tree visibility, not just tested-file visibility).
      all: true,
      include: ['overrides/**/*.{ts,tsx}'],
      exclude: [
        'overrides/**/*.test.{ts,tsx}',
        'overrides/**/*.stories.{ts,tsx}',
        'overrides/**/*.css.ts',
        'overrides/**/*.d.ts',
      ],
      reporter: ['text', 'json-summary', 'html'],
    },
  },
  resolve: {
    // Keep in sync with babel.config.js, tsconfig.json, .storybook/main.js
    // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
    alias: {
      '~': path.resolve(__dirname),
      app: path.resolve(__dirname, 'overrides/app'),
    },
  },
});

=== .storybook/main.js ===
const path = require('path');
const webpack = require('webpack');

/** @type { import('@storybook/react-webpack5').StorybookConfig } */
const config = {
  stories: ['../overrides/**/*.stories.@(js|jsx|ts|tsx|mdx)'],
  // Serve overrides/app/static/ so self-hosted assets resolve in Storybook the same way
  // getAssetUrl resolves them in the app. Mapped to /static (rather than the bare directory)
  // so the fallback path in overrides/app/theme/fontFace.tsx is a real URL here instead of a
  // silent 404 — without this, Storybook renders the fallback font while the app renders
  // Futura Round, and no visual comparison made in Storybook can be trusted.
  staticDirs: [{ from: '../overrides/app/static', to: '/static' }],
  addons: [
    '@storybook/addon-webpack5-compiler-babel',
    '@storybook/addon-links',
    '@storybook/addon-docs',
    '@storybook/addon-a11y',
  ],
  framework: {
    name: '@storybook/react-webpack5',
    options: {},
  },
  webpackFinal: async (webpackConfig) => {
    // Resolve PWA Kit package aliases so imports from
    // '@salesforce/retail-react-app/...' resolve correctly.
    webpackConfig.resolve.alias = {
      ...webpackConfig.resolve.alias,
      // Project path aliases — keep in sync with babel.config.js, tsconfig.json
      // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
      '~': path.resolve(__dirname, '..'),
      app: path.resolve(__dirname, '../overrides/app'),
      '@salesforce/retail-react-app': path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      '@salesforce/pwa-kit-react-sdk': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-react-sdk'),
      '@salesforce/pwa-kit-runtime': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-runtime'),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, '../node_modules/@salesforce/commerce-sdk-react'),
    };

    // Allow Storybook to process JSX inside @salesforce/retail-react-app,
    // which ships un-compiled .jsx source files.
    webpackConfig.module.rules.push({
      test: /\.(js|jsx)$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      use: { loader: 'babel-loader' },
    });

    // @salesforce/pwa-kit-runtime/utils/ssr-config.js branches on this global (normally
    // injected by pwa-kit-dev's own webpack DefinePlugin for the 'web' target) to pick its
    // browser-safe ssr-config.client.js instead of the Node-only ssr-config.server.js, which
    // pulls in `cosmiconfig` (fs/os/module) and breaks the browser bundle. Storybook's webpack
    // config never set this, so the server-only branch was being bundled — see overrides/app
    // /config/contentful.ts, whose getConfig() import triggers it via the footer story.
    webpackConfig.plugins.push(
      new webpack.DefinePlugin({
        WEBPACK_TARGET: "'web'",
      }),
    );

    // Storybook adds a default asset/resource rule that catches all SVGs — remove it
    // so our scoped rules below can take full control.
    webpackConfig.module.rules = webpackConfig.module.rules.filter(
      (rule) => !(rule?.test instanceof RegExp && rule.test.test('.svg')),
    );

    // Mirror the PWA Kit browser build: SFCC SVGs are sprite-loaded server-side only,
    // so the browser (and Storybook) should ignore those imports entirely.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      loader: 'ignore-loader',
    });

    // Treat project SVGs as file assets.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      exclude: /node_modules/,
      type: 'asset/resource',
    });

    return webpackConfig;
  },
};

module.exports = config;

